import { Request, Response } from 'express';
import { CreateProjectUseCase } from '../../application/usecases/CreateProjectUseCase';

export class ProjectController {
  constructor(private createProjectUseCase: CreateProjectUseCase) {}

  createProject(req: Request, res: Response): void {
    try {
      const { name, description } = req.body;

      if (!name || !description) {
        res.status(400).json({
          error: 'Missing required fields: name, description',
        });
        return;
      }

      const project = this.createProjectUseCase.execute({ name, description });
      res.status(201).json(project);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  }
}

