import { Request, Response } from 'express';
import { CreateTaskUseCase } from '../../application/usecases/CreateTaskUseCase';
import { AssignTaskUseCase } from '../../application/usecases/AssignTaskUseCase';
import { MarkTaskAsDoneUseCase } from '../../application/usecases/MarkTaskAsDoneUseCase';
import { ListTasksUseCase } from '../../application/usecases/ListTasksUseCase';
import { TaskStatus } from '../../domain/entities/Task';

export class TaskController {
  constructor(
    private createTaskUseCase: CreateTaskUseCase,
    private assignTaskUseCase: AssignTaskUseCase,
    private markTaskAsDoneUseCase: MarkTaskAsDoneUseCase,
    private listTasksUseCase: ListTasksUseCase,
  ) {}

  createTask(req: Request, res: Response): void {
    try {
      const { projectId, title, description, dueDate } = req.body;

      if (!projectId || !title || !description) {
        res.status(400).json({
          error: 'Missing required fields: projectId, title, description',
        });
        return;
      }

      const task = this.createTaskUseCase.execute({
        projectId,
        title,
        description,
        dueDate,
      });
      res.status(201).json({
        id: task.id,
        projectId: task.projectId,
        title: task.title,
        description: task.description,
        status: task.status,
        dueDate: task.dueDate ? task.dueDate.toISOString() : null,
        assigneeId: task.assigneeId,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  }

  assignTask(req: Request, res: Response): void {
    try {
      const { taskId, userId } = req.body;

      if (!taskId || !userId) {
        res.status(400).json({
          error: 'Missing required fields: taskId, userId',
        });
        return;
      }

      const task = this.assignTaskUseCase.execute(taskId, userId);
      res.json({
        id: task.id,
        projectId: task.projectId,
        title: task.title,
        description: task.description,
        status: task.status,
        dueDate: task.dueDate ? task.dueDate.toISOString() : null,
        assigneeId: task.assigneeId,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  }

  markTaskAsDone(req: Request, res: Response): void {
    try {
      const { taskId } = req.body;

      if (!taskId) {
        res.status(400).json({
          error: 'Missing required field: taskId',
        });
        return;
      }

      const task = this.markTaskAsDoneUseCase.execute(taskId);
      res.json({
        id: task.id,
        projectId: task.projectId,
        title: task.title,
        description: task.description,
        status: task.status,
        dueDate: task.dueDate ? task.dueDate.toISOString() : null,
        assigneeId: task.assigneeId,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  }

  listTasks(req: Request, res: Response): void {
    try {
      const projectId = (req.params.projectId as string) || '';

      if (!projectId) {
        res.status(400).json({
          error: 'Missing required param: projectId',
        });
        return;
      }

      const statusQuery = req.query.status;
      const assigneeQuery = req.query.assigneeId;
      const status =
        typeof statusQuery === 'string' ? statusQuery : undefined;
      const assigneeId =
        typeof assigneeQuery === 'string' ? assigneeQuery : undefined;

      let tasks;
      if (status) {
        tasks = this.listTasksUseCase.executeByStatus(
          projectId,
          status as TaskStatus,
        );
      } else if (assigneeId) {
        tasks = this.listTasksUseCase.executeByAssignee(projectId, assigneeId);
      } else {
        tasks = this.listTasksUseCase.executeAll(projectId);
      }

      const response = tasks.map((task) => ({
        id: task.id,
        projectId: task.projectId,
        title: task.title,
        description: task.description,
        status: task.status,
        dueDate: task.dueDate ? task.dueDate.toISOString() : null,
        assigneeId: task.assigneeId,
      }));

      res.json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  }
}

